from pathlib import Path
import re
p=Path('index.html')
s=p.read_text(encoding='utf-8')

css=r'''
/* DOCUMENT_TEMPLATES_V2 */
.template-note{margin:0 0 12px;padding:12px 14px;border-radius:15px;background:#efe5d9;border:1px solid #dfd0c0;font-size:11px;line-height:1.45;color:#685d54}
.template-fields{display:grid;grid-template-columns:1fr 1fr;gap:11px}
.template-fields label.wide{grid-column:1/-1}
.template-fields textarea{min-height:92px}
.doc-head{margin-left:auto;width:58%;text-align:left;line-height:1.45;margin-bottom:44px}
.doc-title{text-align:center;font-weight:700;text-transform:uppercase;margin:26px 0 24px;font-size:18px}
.doc-subtitle{text-align:center;font-weight:700;margin:-17px 0 24px;font-size:17px}
.doc-body{font-size:16px;line-height:1.55;text-align:justify}
.doc-sign{margin-top:38px;display:flex;justify-content:space-between;gap:20px;font-size:14px}
.doc-sign span:last-child{text-align:right}
.doc-section{margin:17px 0 7px;font-weight:700;font-size:16px}
.doc-table{width:100%;border-collapse:collapse;margin:8px 0 16px;font-size:12px}.doc-table th,.doc-table td{border:1px solid #333;padding:6px;vertical-align:top}.doc-table th{font-weight:700}
.doc-lines{border-bottom:1px solid #555;min-height:22px;margin:4px 0}
.template-toolbar{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.template-toolbar button{flex:1;min-width:125px}
@media(max-width:600px){.template-fields{grid-template-columns:1fr}.template-fields label.wide{grid-column:auto}.doc-head{width:76%}.paper{padding:18px;font-size:14px}.doc-body{font-size:14px}.template-toolbar button{min-width:calc(50% - 4px)}}
'''
if '/* DOCUMENT_TEMPLATES_V2 */' not in s:
    s=s.replace('@media print{',css+'\n@media print{',1)

new_section=r'''<section id="formsView" class="view">
  <div class="page-head"><div class="back-row"><button class="back-link" data-back><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m15 5-7 7 7 7"/></svg>Назад</button></div><div class="page-eyebrow">Документы</div><h2>Бланки и заявления</h2><p>Выберите документ, заполните поля и скачайте готовый файл, сохраните в PDF или отправьте через почту.</p></div>
  <div class="template-note"><b>Важно:</b> реквизиты и ФИО генерального директора в кадровых заявлениях закреплены по действующим образцам и не меняются.</div>
  <div class="forms-list">
    <button class="doc-card" data-template="dismissal"><span class="doc-icon">A4</span><span><b>Заявление на увольнение</b><small>По собственному желанию</small></span><span>›</span></button>
    <button class="doc-card" data-template="vacation"><span class="doc-icon">A4</span><span><b>Заявление на отпуск</b><small>Ежегодный оплачиваемый отпуск</small></span><span>›</span></button>
    <button class="doc-card" data-template="hire"><span class="doc-icon">СЗ</span><span><b>СЗ о приёме на работу</b><small>Кандидат, условия, дата трудоустройства</small></span><span>›</span></button>
    <button class="doc-card" data-template="freelance"><span class="doc-icon">СЗ</span><span><b>СЗ на фриланс</b><small>Привлечение внештатного сотрудника</small></span><span>›</span></button>
    <button class="doc-card" data-template="suspension"><span class="doc-icon">СЗ</span><span><b>СЗ об отстранении</b><small>Период и основание отстранения</small></span><span>›</span></button>
    <button class="doc-card" data-template="candidate"><span class="doc-icon">HR</span><span><b>Анкета кандидата</b><small>Основные сведения и согласие на обработку данных</small></span><span>›</span></button>
    <button class="doc-card" data-template="parent"><span class="doc-icon">18−</span><span><b>Согласие родителя / представителя</b><small>Для несовершеннолетнего</small></span><span>›</span></button>
  </div>
  <div class="card admin-card"><h3>Синхронизация</h3><p><b>АТО, график и подотчёт</b> синхронизируются с Google Sheets. Ревизия и табель пока сохраняются локально.</p><div class="actions-row"><button id="resetPinBtn" class="secondary" type="button">Сменить код доступа</button><button id="exportBtn" class="secondary" type="button">Выгрузить локальные данные</button></div></div>
</section>'''
s,n=re.subn(r'<section id="formsView" class="view">.*?</section>\n</main>',new_section+'\n</main>',s,count=1,flags=re.S)
assert n==1,'formsView not replaced'

new_dialog=r'''<dialog id="templateDialog"><form method="dialog" class="dialog-shell"><div class="dialog-top"><strong id="templateTitle">Документ</strong><button class="ghost" value="cancel">Закрыть</button></div><div id="templateFields" class="template-form template-fields"></div><div id="templatePreview" class="paper"></div><div class="template-toolbar"><button type="button" id="downloadTpl" class="secondary">Скачать документ</button><button type="button" id="emailTpl" class="secondary">Отправить на e-mail</button><button type="button" id="shareTpl" class="secondary">Поделиться</button><button type="button" id="printTpl" class="primary">Печать / PDF</button></div></form></dialog>'''
s,n=re.subn(r'<dialog id="templateDialog">.*?</dialog>',new_dialog,s,count=1,flags=re.S)
assert n==1,'template dialog not replaced'

new_js=r'''// Document templates v2
const dialog=document.getElementById('templateDialog');
const tplTitle=document.getElementById('templateTitle');
const fieldsBox=document.getElementById('templateFields');
const preview=document.getElementById('templatePreview');
let activeTemplate='dismissal';
const DIRECTOR_FULL='Гурьевой Светлане Валерьевне';
const DIRECTOR_SHORT='Гурьевой С.В.';
const COMPANY='ООО «Круассан кафе»';
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function v(id,blank='____________________________'){const e=document.getElementById('tpl_'+id);return e&&e.value.trim()?e.value.trim():blank}
function raw(id){const e=document.getElementById('tpl_'+id);return e?e.value.trim():''}
function fmtDate(vv){return vv?new Date(vv+'T00:00:00').toLocaleDateString('ru-RU'):'____________'}
function fmtLong(vv){if(!vv)return '«___» ____________ 20__ г.';const d=new Date(vv+'T00:00:00');return '«'+String(d.getDate()).padStart(2,'0')+'» '+d.toLocaleDateString('ru-RU',{month:'long'})+' '+d.getFullYear()+' г.'}
function field(id,label,type='text',wide=false,placeholder=''){return {id,label,type,wide,placeholder}}
const templates={
  dismissal:{title:'Заявление на увольнение',fields:[field('role','Должность'),field('department','Подразделение'),field('name','ФИО сотрудника','text',true),field('date','Дата увольнения','date'),field('signed','Дата заявления','date')],build(){return `<div class="doc-head">Генеральному директору<br>${COMPANY}<br>${DIRECTOR_FULL}<br><br>от ${esc(v('role'))}<br>${esc(v('department'))}<br>${esc(v('name'))}</div><div class="doc-title">заявление.</div><div class="doc-body">Прошу уволить меня по собственному желанию с ${esc(fmtLong(raw('date')))}.</div><div class="doc-sign"><span>______________<br><small>(Подпись)</small><br>${esc(fmtDate(raw('signed')))}</span><span>${esc(v('name'))}<br><small>(расшифровка подписи работника)</small></span></div>`}},
  vacation:{title:'Заявление на ежегодный оплачиваемый отпуск',fields:[field('role','Должность'),field('department','Подразделение'),field('name','ФИО сотрудника','text',true),field('start','Дата начала отпуска','date'),field('days','Количество календарных дней'),field('signed','Дата заявления','date')],build(){return `<div class="doc-head">Генеральному директору<br>${COMPANY}<br>${DIRECTOR_FULL}<br><br>от ${esc(v('role'))}<br>${esc(v('department'))}<br>${esc(v('name'))}</div><div class="doc-title">заявление.</div><div class="doc-body">Прошу предоставить мне ежегодный оплачиваемый отпуск с ${esc(fmtLong(raw('start')))} сроком на ${esc(v('days','________'))} календарных дней.</div><div class="doc-sign"><span>______________<br><small>(Подпись)</small><br>${esc(fmtDate(raw('signed')))}</span><span>${esc(v('name'))}<br><small>(расшифровка подписи работника)</small></span></div>`}},
  hire:{title:'Служебная записка о приёме на работу',fields:[field('managerRole','Должность автора'),field('managerObject','Объект / подразделение'),field('managerName','ФИО автора','text',true),field('candidate','ФИО кандидата','text',true),field('birth','Дата рождения','date'),field('hireDate','Дата трудоустройства','date'),field('training','Смены обучения','textarea',true,'Например: 04.08 — 13 ч; 05.08 — 13 ч'),field('object','Объект'),field('position','Должность'),field('rate','Ставка'),field('schedule','График'),field('memoDate','Дата СЗ','date'),field('extra','Дополнительные условия','textarea',true)],build(){return `<div class="doc-head">Генеральному директору<br>${COMPANY}<br>${DIRECTOR_SHORT}<br><br>От ${esc(v('managerRole'))} ${esc(v('managerObject'))}<br>${esc(v('managerName'))}</div><div class="doc-title">Служебная записка</div><div class="doc-subtitle">о приеме на работу</div><div class="doc-body"><p>1. Прошу согласовать кандидатуру — <b>${esc(v('candidate'))}</b>${raw('birth')?', '+esc(fmtDate(raw('birth')))+' года рождения':''}.</p><p>2. После успешного согласования прошу оформить кандидата на работу в штат.</p><p><b>Дата трудоустройства:</b> ${esc(fmtDate(raw('hireDate')))}<br><b>Смены обучения:</b> ${esc(v('training','—'))}<br><b>Объект:</b> ${esc(v('object'))}<br><b>Должность:</b> ${esc(v('position'))}<br><b>Ставка:</b> ${esc(v('rate'))}<br><b>График:</b> ${esc(v('schedule'))}</p><p>3. Кандидат предупрежден о необходимости прохождения стандартных процедур при приеме на работу, принятых в организации. Готовность кандидата приступить к обязанностям с указанной даты подтверждена.</p>${raw('extra')?'<p>'+esc(raw('extra'))+'</p>':''}</div><div class="doc-sign"><span>${esc(fmtDate(raw('memoDate')))}</span><span>${esc(v('managerName'))}</span></div>`}},
  freelance:{title:'Служебная записка на фриланс',fields:[field('managerRole','Должность автора'),field('managerObject','Объект / подразделение'),field('managerName','ФИО автора','text',true),field('person','ФИО фрилансера','text',true),field('position','Должность'),field('category','Категория / ставка'),field('from','Период с','date'),field('to','Период по','date'),field('reason','Причина привлечения','textarea',true),field('memoDate','Дата СЗ','date')],build(){return `<div class="doc-head">Генеральному директору<br>${COMPANY}<br>${DIRECTOR_SHORT}<br><br>от ${esc(v('managerRole'))}<br>${esc(v('managerObject'))}<br>${esc(v('managerName'))}</div><div class="doc-title">СЛУЖЕБНАЯ ЗАПИСКА</div><div class="doc-body">Прошу разрешить привлечь фрилансом <b>${esc(v('person'))}</b> на должность ${esc(v('position'))}${raw('category')?' ('+esc(raw('category'))+')':''} с ${esc(fmtDate(raw('from')))} по ${esc(fmtDate(raw('to')))}${raw('reason')?' в связи с '+esc(raw('reason')):''}.</div><div class="doc-sign"><span>${esc(fmtDate(raw('memoDate')))}</span><span>${esc(v('managerName'))}</span></div>`}},
  suspension:{title:'Служебная записка об отстранении от работы',fields:[field('managerRole','Должность автора'),field('managerName','ФИО автора'),field('employee','ФИО сотрудника','text',true),field('employeeRole','Должность сотрудника'),field('object','Объект'),field('from','Отстранить с','date'),field('to','Отстранить по','date'),field('reason','Причина','textarea',true),field('agreement','Согласование / комментарий','text',true,'Например: С ОД согласовано.'),field('memoDate','Дата СЗ','date')],build(){return `<div class="doc-head">Генеральному директору<br>${COMPANY}<br>${DIRECTOR_SHORT}<br><br>от ${esc(v('managerRole'))}<br>${esc(v('managerName'))}</div><div class="doc-title">Служебная записка</div><div class="doc-subtitle">Об отстранении от работы</div><div class="doc-body">Прошу отстранить от работы ${esc(v('employeeRole'))} <b>${esc(v('employee'))}</b>, ${esc(v('object'))}, от работы с ${esc(fmtDate(raw('from')))} по ${esc(fmtDate(raw('to')))}${raw('reason')?' в связи с '+esc(raw('reason')):''}.<br><br>${esc(v('agreement',''))}</div><div class="doc-sign"><span>${esc(fmtDate(raw('memoDate')))}</span><span>${esc(v('managerName'))}</span></div>`}},
  candidate:{title:'Анкета кандидата',fields:[field('position','Должность, на которую претендуете','text',true),field('surname','Фамилия'),field('name','Имя'),field('patronymic','Отчество'),field('oldSurname','Прежняя фамилия'),field('birth','Дата рождения','date'),field('citizenship','Гражданство'),field('marital','Семейное положение'),field('birthPlace','Место рождения','text',true),field('phone','Контактный телефон'),field('registration','Адрес по прописке','textarea',true),field('actual','Фактическое место проживания','textarea',true),field('passport','Паспортные данные','textarea',true),field('military','Воинская обязанность / звание','textarea',true),field('education','Образование','textarea',true),field('driving','Водительские права / автомобиль','text',true),field('computer','Опыт работы с компьютером / языки','textarea',true),field('work','Трудовая деятельность за последние 7 лет','textarea',true),field('reference','Руководитель с предыдущего места работы','textarea',true),field('salary','Желаемая заработная плата'),field('relatives','Близкие родственники','textarea',true),field('special','Особый статус / подтверждающие документы','textarea',true),field('source','Источник вакансии'),field('criminal','Уголовная / административная ответственность','textarea',true),field('relativesCriminal','Ответственность близких родственников','textarea',true),field('obligations','Кредиты, ссуды, алименты','textarea',true),field('organizations','Общественные / профсоюзные организации','textarea',true),field('service','Гос., муниципальная или военная служба','textarea',true),field('business','Предпринимательская деятельность / участие в организациях','textarea',true),field('signed','Дата заполнения','date')],build(){return `<div class="doc-title">АНКЕТА</div><div class="doc-body"><div class="doc-section">Должность</div>${esc(v('position'))}<div class="doc-section">Персональные данные</div><b>Фамилия:</b> ${esc(v('surname'))}<br><b>Имя:</b> ${esc(v('name'))}<br><b>Отчество:</b> ${esc(v('patronymic'))}<br><b>Прежняя фамилия:</b> ${esc(v('oldSurname','—'))}<br><b>Дата рождения:</b> ${esc(fmtDate(raw('birth')))}<br><b>Гражданство:</b> ${esc(v('citizenship'))}<br><b>Семейное положение:</b> ${esc(v('marital'))}<br><b>Место рождения:</b> ${esc(v('birthPlace'))}<br><b>Контактный телефон:</b> ${esc(v('phone'))}<div class="doc-section">Адреса и документы</div><b>Адрес по прописке:</b> ${esc(v('registration'))}<br><b>Фактическое место проживания:</b> ${esc(v('actual'))}<br><b>Паспортные данные:</b> ${esc(v('passport'))}<br><b>Воинская обязанность:</b> ${esc(v('military'))}<div class="doc-section">Образование и навыки</div>${esc(v('education'))}<br><b>Водительские права / автомобиль:</b> ${esc(v('driving','—'))}<br><b>Компьютер / языки:</b> ${esc(v('computer'))}<div class="doc-section">Трудовая деятельность за последние 7 лет</div>${esc(v('work'))}<div class="doc-section">Рекомендации</div>${esc(v('reference'))}<br><b>Желаемая заработная плата:</b> ${esc(v('salary'))}<div class="doc-section">Близкие родственники</div>${esc(v('relatives'))}<div class="doc-section">Дополнительные сведения</div><b>Особый статус:</b> ${esc(v('special','—'))}<br><b>Источник вакансии:</b> ${esc(v('source'))}<br><b>Привлекались к ответственности:</b> ${esc(v('criminal','—'))}<br><b>Близкие родственники привлекались:</b> ${esc(v('relativesCriminal','—'))}<br><b>Обязательства:</b> ${esc(v('obligations','—'))}<br><b>Общественные / профсоюзные организации:</b> ${esc(v('organizations','—'))}<br><b>Государственная / муниципальная / военная служба:</b> ${esc(v('service','—'))}<br><b>Предпринимательская деятельность:</b> ${esc(v('business','—'))}<div class="doc-section">Согласие на обработку персональных данных</div>Я, ${esc(v('surname','________'))} ${esc(v('name','________'))} ${esc(v('patronymic','________'))}, свободно, своей волей и в своем интересе даю согласие ООО «Европейские кондитерские» (г. Калининград, ул. Вагоностроительная, 22 пом.2) на обработку в документальной и/или электронной форме моих персональных данных в целях рассмотрения моей кандидатуры на вакантную должность. Настоящее согласие действует с даты подписания до окончания календарного года, в котором оно было подписано, и может быть отозвано в письменной форме.</div><div class="doc-sign"><span>Дата заполнения: ${esc(fmtDate(raw('signed')))}</span><span>Личная подпись: ____________</span></div>`}},
  parent:{title:'Согласие родителя / законного представителя',fields:[field('representative','ФИО законного представителя','text',true),field('passportSeries','Паспорт: серия'),field('passportNumber','Паспорт: номер'),field('issueDate','Дата выдачи','date'),field('issuedBy','Кем выдан','textarea',true),field('address','Адрес проживания','textarea',true),field('phone','Мобильный телефон'),field('email','E-mail'),field('minor','ФИО несовершеннолетнего','text',true),field('minorDoc','Документ несовершеннолетнего','textarea',true),field('minorAddress','Адрес несовершеннолетнего','textarea',true),field('basis','Статус представителя','text',true,'родитель / усыновитель / попечитель'),field('authorityDoc','Документ о полномочиях','textarea',true),field('signed','Дата','date')],build(){return `<div class="doc-title">С О Г Л А С И Е</div><div class="doc-subtitle">родителя/законного представителя</div><div class="doc-body">Я, <b>${esc(v('representative'))}</b>, паспорт серия ${esc(v('passportSeries'))} номер ${esc(v('passportNumber'))}, дата выдачи ${esc(fmtDate(raw('issueDate')))}, выдан ${esc(v('issuedBy'))}, проживающий(ая) по адресу: ${esc(v('address'))}, номер мобильного телефона: ${esc(v('phone'))}, e-mail: ${esc(v('email'))}, являясь законным представителем несовершеннолетнего <b>${esc(v('minor'))}</b> (${esc(v('basis'))}), подтверждаю, что даю такое согласие добровольно и в интересах несовершеннолетнего.<br><br><b>Данные документа несовершеннолетнего:</b> ${esc(v('minorDoc'))}<br><b>Адрес несовершеннолетнего:</b> ${esc(v('minorAddress'))}<br><b>Документ, подтверждающий полномочия законного представителя:</b> ${esc(v('authorityDoc','—'))}.<br><br>Настоящим даю свое согласие ПАО «Банк «Санкт-Петербург», адрес регистрации Санкт-Петербург, Малоохтинский пр., д.64-А, на действия и обработку персональных данных несовершеннолетнего в объеме, предусмотренном предоставленным образцом согласия, включая оказание банковских услуг, выпуск платежных карт, получение информации Банка, обработку и передачу персональных данных, а также предоставление доступа к Интернет-банку.</div><div class="doc-sign"><span>Дата: ${esc(fmtDate(raw('signed')))}</span><span>Подпись законного представителя: ____________</span></div>`}}
};
function renderFields(){const t=templates[activeTemplate];fieldsBox.innerHTML=t.fields.map(f=>{const tag=f.type==='textarea'?`<textarea id="tpl_${f.id}" placeholder="${esc(f.placeholder||'')}"></textarea>`:`<input id="tpl_${f.id}" type="${f.type||'text'}" placeholder="${esc(f.placeholder||'')}">`;return `<label class="${f.wide?'wide':''}">${esc(f.label)}${tag}</label>`}).join('');fieldsBox.querySelectorAll('input,textarea').forEach(x=>x.addEventListener('input',buildTemplate));t.fields.filter(f=>f.type==='date').forEach(f=>{const e=document.getElementById('tpl_'+f.id);if(e)e.value=today});}
function buildTemplate(){preview.innerHTML=templates[activeTemplate].build()}
function openTemplate(key){activeTemplate=key;tplTitle.textContent=templates[key].title;renderFields();buildTemplate();dialog.showModal()}
document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>openTemplate(b.dataset.template));
function documentHtml(){buildTemplate();return `<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:"Times New Roman",serif;font-size:14pt;line-height:1.45;margin:20mm}.doc-head{margin-left:auto;width:58%;margin-bottom:35px}.doc-title{text-align:center;font-weight:bold;text-transform:uppercase;margin:22px 0}.doc-subtitle{text-align:center;font-weight:bold;margin:-14px 0 22px}.doc-body{text-align:justify}.doc-sign{margin-top:34px;display:flex;justify-content:space-between;gap:20px}.doc-section{margin:14px 0 5px;font-weight:bold}</style></head><body>${preview.innerHTML}</body></html>`}
function fileName(){return templates[activeTemplate].title.replace(/[\\/:*?"<>|]+/g,'_')+'.doc'}
function makeFile(){return new File([documentHtml()],fileName(),{type:'application/msword'})}
document.getElementById('downloadTpl').onclick=()=>{const f=makeFile(),a=document.createElement('a');a.href=URL.createObjectURL(f);a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
document.getElementById('emailTpl').onclick=()=>{buildTemplate();const subject=encodeURIComponent(templates[activeTemplate].title);const body=encodeURIComponent(preview.innerText);location.href=`mailto:?subject=${subject}&body=${body}`};
document.getElementById('shareTpl').onclick=async()=>{try{const f=makeFile();if(navigator.share&&navigator.canShare&&navigator.canShare({files:[f]}))await navigator.share({title:templates[activeTemplate].title,files:[f]});else if(navigator.share)await navigator.share({title:templates[activeTemplate].title,text:preview.innerText});else notify('На этом устройстве используйте «Скачать документ»')}catch(e){if(e.name!=='AbortError')notify('Не удалось открыть меню отправки')}};
document.getElementById('printTpl').onclick=()=>{buildTemplate();print()};'''
s,n=re.subn(r'// Document templates\n.*?</script>',new_js+'\n</script>',s,count=1,flags=re.S)
assert n==1,'document JS not replaced'
p.write_text(s,encoding='utf-8')
